versions.variantCss:
.wemd-code-frame[data-variant="bytedance-codeframe-mac"] {
  background: #1a1a1a;
  border-radius: 12px;
  padding: 0;
  margin: 16px 0;
  overflow: hidden;
  border: 1px solid #2a2a2a;
}
.wemd-code-frame[data-variant="bytedance-codeframe-mac"] .wemd-component-body {
  padding: 0;
}
.wemd-code-frame[data-variant="bytedance-codeframe-mac"] .wemd-component-body .wemd-child-1 {
  background: #2a2a2a;
  color: var(--wemd-text-soft);
  font-size: 12px;
  font-weight: 500;
  padding: 10px 16px;
  margin: 0;
  border-bottom: 1px solid #3a3a3a;
}
.wemd-code-frame[data-variant="bytedance-codeframe-mac"] .wemd-component-body .wemd-child-2 {
  color: #e5e7eb;
  font-family: 'JetBrains Mono', 'SF Mono', Consolas, monospace;
  font-size: 13px;
  line-height: 1.7;
  padding: 16px 20px;
  margin: 0;
  white-space: pre;
}
